// 1. Lấy toàn bộ danh sách parts từ AI
const parts = $input.first().json.content.parts;

// 2. Tự động lấy part cuối cùng (nơi chứa kết quả JSON thực sự)
let rawText = parts[parts.length - 1].text;

// (Dự phòng an toàn): Nếu part cuối không chứa cấu trúc JSON mong muốn, tìm part có chứa chữ "intent"
if (!rawText.includes('"intent"')) {
    let targetPart = parts.find(p => p.text && p.text.includes('"intent"'));
    if (targetPart) rawText = targetPart.text;
}

// 3. Làm sạch chuỗi và chuyển đổi sang JSON
rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

// Xử lý thêm: Cắt bỏ các text rác có thể bị AI chèn vào trước/sau ngoặc nhọn
const start = rawText.indexOf('{');
const end = rawText.lastIndexOf('}');
if (start !== -1 && end !== -1) {
    rawText = rawText.substring(start, end + 1);
}

let parsed = JSON.parse(rawText);

const validSheets = ["ĐÀ NẴNG (TRUNG LẬP)", "DAKLAK", "GIALAI", "KHÁNH HÒA", "ĐỒNG NAI", "CẦN THƠ", "BÌNH DƯƠNG", "VŨNG TÀU", "NINH BÌNH", "VĨNH LONG", "AN GIANG", "QUẢNG NINH", "ĐÀ NẴNG (C.HỒNG)", "PHAN THIẾT", "PAGE A.THẮNG", "PLEIKU", "ĐÀ NẴNG (SƠN)", "HCM", "ĐỒNG THÁP", "KON TUM", "VĨNH PHÚC", "CÀ MAU", "ĐÀ NẴNG (TRUNG LẬP) 2", "LẠNG SƠN", "THÁI BÌNH", "QUẢNG NGÃI", "PHÚ YÊN", "HUẾ", "QUẢNG TRỊ", "NHA TRANG", "SÀI GÒN"];

function standardize(name) {
  if (!name) return "";
  let iName = name.trim().toUpperCase();
  let cName = iName.replace(/^PAGE\s+/i, '').trim();
  let normalize = (str) => str.replace(/[\s\(\)\.\-]/g, '').toUpperCase();
  let f = validSheets.find(s => s === iName || s === cName);
  if (!f) f = validSheets.find(s => normalize(s) === normalize(iName) || normalize(s) === normalize(cName));
  if (!f) f = validSheets.find(s => s.includes(cName) || cName.includes(s));
  return f || iName;
}

if (parsed.intent === 'nhập_liệu') {
  let updates = Array.isArray(parsed.updates) ? parsed.updates : [parsed];
  return updates.map(u => ({
      json: {
          intent: 'nhập_liệu',
          sheet_name: standardize(u.sheet_name || parsed.sheet_name),
          leads: Number(u.leads || parsed.leads || 0),
          pttb: Number(u.pttb || parsed.pttb || 0)
      }
  }));
}

return [ { json: parsed } ];

