// Lấy dữ liệu từ Apps Script (báo cáo hôm nay)
const appsScriptData = $('Gọi Apps Script (Báo Cáo)').first().json;

// Lấy danh sách page từ DASHBOARD
const dashboardItems = $input.all();

// Lọc ra các page đang chạy (Tình trạng = 'Đang chạy')
const runningPages = dashboardItems
  .filter(item => {
    const status = (item.json['Tình trạng'] || item.json['TÌNH TRẠNG'] || '').trim();
    return status === 'Đang chạy';
  })
  .map(item => {
    // Tên cột trong DASHBOARD là 'Tỉnh/Page' (cột A, hàng 3)
    return (
      item.json['Tỉnh/Page'] ||
      item.json['Tên Page'] ||
      item.json['TÊN PAGE'] ||
      item.json['Page'] ||
      item.json['PAGE'] ||
      ''
    ).trim();
  })
  .filter(name => name !== '');

// Hàm chuẩn hóa tên để so sánh
const normalize = (str) => str.replace(/[\s\(\)\.\-]/g, '').toUpperCase();

// Lấy danh sách page đã có dữ liệu hôm nay từ Apps Script
let effectivePages = [];

// Phân tích từ rows nếu có (Apps Script trả về mảng rows)
if (appsScriptData.rows && Array.isArray(appsScriptData.rows)) {
  effectivePages = appsScriptData.rows
    .filter(row => Number(row.leads || row.LEADS || row['TỔNG SỐ ĐIỆN THOẠI'] || 0) > 0 ||
                   Number(row.pttb || row.PTTB || row['TỔNG PTTB'] || 0) > 0)
    .map(row => row.page || row.PAGE || row.name || row.sheet || '');
}

// Nếu không có rows, phân tích từ details_text
if (effectivePages.length === 0 && appsScriptData.details_text) {
  const lines = appsScriptData.details_text.split('\n');
  for (const line of lines) {
    const leadsMatch = line.match(/(\d+)\s*leads?/i);
    const pttbMatch = line.match(/(\d+)\s*pttb/i);
    const leads = leadsMatch ? Number(leadsMatch[1]) : 0;
    const pttb = pttbMatch ? Number(pttbMatch[1]) : 0;

    if (leads > 0 || pttb > 0) {
      const colonIdx = line.indexOf(':');
      if (colonIdx > 0) {
        const pageName = line.substring(0, colonIdx).replace(/^[\s\uD83D\uDCCC\-\*•]+/, '').trim();
        if (pageName) effectivePages.push(pageName);
      }
    }
  }
}

// Tìm page đang chạy nhưng CHƯA hiệu quả (không có trong danh sách hiệu quả)
const ineffectivePages = runningPages.filter(runPage => {
  const isEffective = effectivePages.some(effPage =>
    normalize(effPage) === normalize(runPage) ||
    normalize(effPage).includes(normalize(runPage)) ||
    normalize(runPage).includes(normalize(effPage))
  );
  return !isEffective;
});

// Tạo text hiển thị
let ineffectivePagesText = '';
if (ineffectivePages.length > 0) {
  ineffectivePagesText = '\n\n⚠️ Page chưa hiệu quả: ' + ineffectivePages.join(', ');
} else {
  ineffectivePagesText = '\n\n✅ Tất cả page đang chạy đều có hiệu quả!';
}

// Trả về dữ liệu đầy đủ
return [{
  json: {
    ...appsScriptData,
    ineffective_pages: ineffectivePages,
    ineffective_pages_text: ineffectivePagesText,
    running_pages: runningPages,
    effective_pages: effectivePages
  }
}];

const pages = [
  "PAGE ANH THẮNG", "Hà Nội (A.Thắng)", "Quảng Ninh", "PAGE CHỊ CHI", "CÀ MAU", 
  "ĐỒNG THÁP", "HCM (C.CHI)", "DAKLAK", "TÂY NINH", "Page A.Thắng", 
  "Hà Nội (Đ.Anh)", "PAGE CHỊ HOÀNG", "Hưng Yên (C.Hoàng)", "PHÚ THỌ (C.HOÀNG)", 
  "GIALAI", "LÂM ĐỒNG", "CẦN THƠ", "BÌNH DƯƠNG", "VĨNH LONG", "AN GIANG", 
  "HUẾ", "ĐỒNG NAI", "KHÁNH HÒA", "QUẢNG NGÃI", "HẢI DƯƠNG", "NINH BÌNH", 
  "Thanh Hóa", "NGHỆ AN", "QUẢNG TRỊ", "PAGE CHỊ TIÊN", "Bắc Ninh (Tiên)", 
  "Thái Nguyên", "ĐÀ NẴNG (TRUNG LẬP)", "QUẢNG NAM", "TOÀN QUỐC", "PAGE C.TRÂM", 
  "HCM (TRÂM)", "Bắc Ninh (Trâm)", "HCM (KIM CHI)", "Vĩnh Phúc"
];

return $input.all().map(item => {
  const json = item.json;
  const page_name = json.page_name || '';
  const online_count = Number(json.online_count) || 0;

  const normalize = (str) => str.replace(/[\s\(\)\.\-]/g, '').toLowerCase();

  let rowIndex = -1;
  for(let i=0; i<pages.length; i++) {
     if(pages[i].toLowerCase() === page_name.toLowerCase()) {
        rowIndex = i; break;
     }
  }
  if(rowIndex === -1) {
     for(let i=0; i<pages.length; i++) {
        if(normalize(pages[i]) === normalize(page_name)) {
           rowIndex = i; break;
        }
     }
  }
  if(rowIndex === -1) {
     for(let i=0; i<pages.length; i++) {
        if(pages[i].toLowerCase().includes(page_name.toLowerCase()) || page_name.toLowerCase().includes(pages[i].toLowerCase())) {
           rowIndex = i; break;
        }
     }
  }
  if(rowIndex === -1) {
    throw new Error("LỖI: Không tìm thấy Page nào phù hợp với: " + page_name);
  }

  const rowNum = 2 + rowIndex;

  return {
    json: {
      ...json,
      "TÊN FANPAGE": pages[rowIndex],
      "row_number": rowNum,
      "Số Online": online_count,
      "page_name": page_name,
      "matchedPage": pages[rowIndex],
      "online_count_new": online_count
    }
  };
});

