const items = $input.all();
const matchedPages = [];
const onlineCounts = [];
const pageNames = [];

for (const item of items) {
  const json = item.json;
  matchedPages.push(json['TÊN FANPAGE'] || json.matchedPage || "Không rõ");
  // Pick whichever case has data
  let count = json['Số online'];
  if (count === undefined || count === null) count = json['Số Online'];
  if (count === undefined || count === null) count = 0;

  onlineCounts.push(count);
  pageNames.push(json.page_name || json['TÊN FANPAGE'] || "Không rõ");
}

return [{
  json: {
    matchedPage: matchedPages,
    online_count: onlineCounts,
    page_name: pageNames
  }
}];

const intentItems = $('Switch Intent').all();
return $input.all().map((item, i) => ({
  json: { ...(intentItems[i] ? intentItems[i].json : {}), ...item.json },
  pairedItem: { item: i }
}));

